import tau2.domains.airline.data_model as dm
from typing import Literal, Annotated, Dict, Optional, Union
from pydantic import BaseModel, Field

dm.CabinClass = Literal["business", "economy", "basic_economy", "premium_economy"]
dm.SeatPrices = Annotated[dict[dm.CabinClass, int], Field(description="P")]
dm.AvailableSeats = Annotated[dict[dm.CabinClass, int], Field(description="S")]

class PA(BaseModel):
    status: Literal["available"] = Field(description="a")
    available_seats: dm.AvailableSeats = Field(description="s")
    prices: dm.SeatPrices = Field(description="p")

dm.FlightDateStatusAvailable = PA
dm.FlightDateStatus = Union[PA, dm.FlightDateStatusLanded, dm.FlightDateStatusCancelled, dm.FlightDateStatusDelayed, dm.FlightDataStatusFlying, dm.FlightDataStatusOnTime]

class PF(dm.FlightBase):
    scheduled_departure_time_est: str = Field(description="d")
    scheduled_arrival_time_est: str = Field(description="a")
    dates: Dict[str, dm.FlightDateStatus] = Field(description="d")

class PDF(dm.FlightBase):
    status: Literal["available"] = Field(description="a")
    scheduled_departure_time_est: str = Field(description="d")
    scheduled_arrival_time_est: str = Field(description="a")
    date: Optional[str] = Field(description="d", default=None)
    available_seats: dm.AvailableSeats = Field(description="s")
    prices: dm.SeatPrices = Field(description="p")

dm.Flight = PF
dm.DirectFlight = PDF

